import {landMaterial} from './land-materials.js';
import * as T from './vendor/three.module.js';
import {citizenModel} from './chapter-two-models.js';
import {C5_STATS,C5_COMBAT} from './chapter-five-data.js';
export function chapterFiveCitizen(parent,x,z,options,palette){const race=options.race,n=citizenModel(parent,x,z,{...options,scale:race==='dwarf'?.8:1.05},palette),g=n.g;
 const add=(geometry,color,px,py,pz)=>{const m=new T.Mesh(geometry,new T.MeshStandardMaterial({color,roughness:.85}));m.position.set(px,py,pz);g.add(m);return m};
 if(race==='dwarf'){g.scale.x*=1.22;g.scale.z*=1.1;if(!options.woman){const beard=add(new T.ConeGeometry(.2,.55,7),0x9b7953,0,1.45,.22);beard.rotation.z=Math.PI;add(new T.TorusGeometry(.13,.025,5,10),0xbb9758,0,1.42,.34)}if(options.woman)for(const side of [-1,1]){const braid=add(new T.CapsuleGeometry(.045,.36,3,6),0x735331,side*.2,1.57,-.09);braid.rotation.z=side*.12;}}
 if(race==='dusk'){g.traverse(m=>{if(m.isMesh&&m.material.userData?.atlasCell===0){m.material=m.material.clone();m.material.color.setHex(0x9ebfc8)}});for(const side of [-1,1]){const ear=add(new T.ConeGeometry(.07,.38,5),0x9ebfc8,side*.25,1.83,0);ear.rotation.z=-side*1.05}add(new T.OctahedronGeometry(.075),0x87cbbf,0,1.35,.19);}
 n.race=race;return n;
}
export function chapterFiveActor(parent,role,x,z,palette,id){const combat=C5_COMBAT[role],n=chapterFiveCitizen(parent,x,z,{id,name:{c5_raider:'Наёмник сборщика',c5_slinger:'Цепной стрелок',c5_shaman:'Кровопевец',c5_brute:'Рудничный голем',c5_wraith:'Стеклянная тень',c5_overseer:'Моркан — сборщик крови'}[role],role:combat==='marksman'?'crossbow':combat==='cantor'||combat==='hag'?'mage':combat==='baron'?'vampire':'sword',cloth:role==='c5_shaman'?10:role==='c5_overseer'?4:7,skin:0,race:role==='c5_brute'?'dwarf':role==='c5_wraith'?'dusk':null},palette);
 if(role==='c5_brute'){const g=n.g;g.scale.set(1.6,1.35,1.5);const limbs=g.children.filter(c=>c.isGroup&&c.position.y===.9);g.traverse(m=>{if(m.isMesh||m.isLine)m.visible=false});const stone=landMaterial('rock',0x82988b),glow=new T.MeshBasicMaterial({color:0x7ad9b9});const piece=(parent,geo,mat,px,py,pz)=>{const m=new T.Mesh(geo,mat);m.position.set(px,py,pz);parent.add(m);return m};piece(g,new T.DodecahedronGeometry(.47,1),stone,0,1.17,0).scale.set(1.15,1,.7);piece(g,new T.DodecahedronGeometry(.26,0),stone,0,1.78,0);piece(g,new T.OctahedronGeometry(.15),glow,0,1.18,.33);for(const side of [-1,1])piece(g,new T.BoxGeometry(.07,.04,.03),glow,side*.09,1.82,.23);for(const arm of g.userData.arms){piece(arm,new T.DodecahedronGeometry(.23,0),stone,0,-.15,0);piece(arm,new T.CapsuleGeometry(.14,.25,3,7),stone,0,-.43,0);piece(arm,new T.DodecahedronGeometry(.22,0),stone,0,-.66,.03)}for(const leg of limbs){piece(leg,new T.CapsuleGeometry(.14,.43,3,7),stone,0,-.32,0);piece(leg,new T.BoxGeometry(.29,.2,.4),stone,0,-.77,.07)}}
 if(role==='c5_wraith'){n.g.traverse(m=>{if(m.isMesh){m.material=m.material.clone();m.material.color.setHex(0x83aebb);m.material.metalness=.3;m.material.roughness=.25}});const veil=new T.Mesh(new T.ConeGeometry(.33,.75,9,1,true),landMaterial('rock',0x425d72));veil.position.y=1.79;n.g.add(veil);for(let i=0;i<5;i++){const shard=new T.Mesh(new T.OctahedronGeometry(.12),new T.MeshStandardMaterial({color:0xa3e0dc,emissive:0x275f69,emissiveIntensity:.4}));shard.position.set(Math.sin(i*2)*.4,1.3+i*.12,Math.cos(i*2)*.28);shard.scale.y=1.8;n.g.add(shard)}}
 if(role==='c5_overseer'){n.g.scale.setScalar(1.28);for(const side of [-1,1]){const horn=new T.Mesh(new T.ConeGeometry(.12,.6,6),new T.MeshStandardMaterial({color:0x9e7458}));horn.position.set(side*.23,2.1,0);horn.rotation.z=-side*.35;n.g.add(horn)}}
 Object.assign(n,{id,role,chapterThree:true,chapterTwo:true,species:role,hp:C5_STATS[role].hp,maxHp:C5_STATS[role].hp,fixedLevel:C5_STATS[role].level,home:new T.Vector3(x,0,z),target:new T.Vector3(x,0,z),heading:0,generation:0,hit:false,aggro:null,timer:0,cooldown:1,windup:0,special:4,block:0,blockReady:4,flightLeft:0,flightReady:8,flightTarget:null,pending:'normal',phase:1,addsUsed:false,height:role==='c5_brute'?2.6:role==='c5_overseer'?2.4:1.8});return n;
}
